code='''def transform(grid):
    # Separator rows and columns are color 2; count marker-color cells per compartment.
    rows=[]; start=0
    for r,row in enumerate(grid):
        if all(v==2 for v in row):
            if r>start: rows.append((start,r))
            start=r+1
    if start<len(grid): rows.append((start,len(grid)))
    cols=[]; start=0
    for c in range(len(grid[0])):
        if all(row[c]==2 for row in grid):
            if c>start: cols.append((start,c))
            start=c+1
    if start<len(grid[0]): cols.append((start,len(grid[0])))
    marker=max(max(row) for row in grid)
    return [[1 if sum(grid[r][c]==marker for r in range(a,b) for c in range(x,y))>=2 else 9
             for x,y in cols] for a,b in rows]
'''
open(p,'w').write(code)
